import java.util.Scanner;
public class JRentCar1 {
	public static void main(String[] args) {
		//Khutwa 1: qira al-madkhalat min wakeel tajir al-sayyarat
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil umr al-ameel:");
		int age = scan.nextInt();
		System.out.println("Adkhil ma idha kana al-ameel ladayh rukhsa qiyada (true or false):");
		boolean hasLicense = scan.nextBoolean();			
		scan.close();
		//Khutwa 2: uktub al-ta'bir al-mantiqi litaqdir mada idha kan al-ameel yastati istijar sayara
		boolean canRentCar = age >= 21 && hasLicense;
		System.out.println(canRentCar);
	}
}
